"use client";

import React, { useState } from "react";
import * as LucideIcons from "lucide-react";
import { Button } from "../../../components/ui/Button";

// Safe icon renderer
function Icon({ name, className }: { name: string, className?: string }) {
    const LucideIcon = (LucideIcons as any)[name];
    if (!LucideIcon) return <div className={className} style={{ width: '20px', height: '20px', backgroundColor: '#333', borderRadius: '4px' }} />;
    return <LucideIcon className={className} />;
}

export default function AdminProfissionais() {
    const [barbers] = useState([
        { id: 1, name: "Marciel Santos", role: "Master Barber", commission: "60%", active: true, rating: "5.0" },
        { id: 2, name: "Thiago Silva", role: "Senior Barber", commission: "50%", active: true, rating: "4.9" },
        { id: 3, name: "Junior Lima", role: "Barber", commission: "45%", active: true, rating: "4.8" },
    ]);

    return (
        <div className="min-h-screen bg-[#0a0a0a] text-white p-6 lg:p-12 font-sans selection:bg-[#D4AF37] selection:text-black animate-fade-in-up">
            <header className="mb-10 flex justify-between items-center">
                <div>
                    <h1 className="text-3xl font-semibold mb-1">
                        Equipe de <span className="text-[#D4AF37]">Profissionais</span>
                    </h1>
                    <p className="text-gray-400 text-sm">Gerencie sua equipe, comissões e horários</p>
                </div>
                <Button className="gap-2">
                    <Icon name="UserPlus" className="w-4 h-4" /> Novo Barbeiro
                </Button>
            </header>

            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
                {barbers.map((barber) => (
                    <div key={barber.id} className="bg-[#111111] border border-[#1f1f1f] rounded-2xl p-8 relative group hover:border-[#D4AF37]/40 transition-all">
                        <div className="absolute top-4 right-4 text-[#D4AF37] opacity-40">
                            <Icon name="Scissors" className="w-8 h-8 rotate-45" />
                        </div>

                        <div className="flex flex-col items-center text-center mb-8">
                            <div className="w-20 h-20 rounded-full bg-[#D4AF37]/10 border border-[#D4AF37]/20 flex items-center justify-center mb-4 overflow-hidden">
                                <img src={`https://api.dicebear.com/7.x/avataaars/svg?seed=${barber.name}`} alt={barber.name} className="w-full h-full object-cover" />
                            </div>
                            <h3 className="text-xl font-bold text-white mb-1 uppercase tracking-tight">{barber.name}</h3>
                            <p className="text-[#D4AF37] text-xs uppercase tracking-[0.3em] font-medium">{barber.role}</p>
                        </div>

                        <div className="grid grid-cols-2 gap-4 mb-8">
                            <div className="bg-[#0a0a0a] p-4 rounded-xl border border-[#1f1f1f] text-center">
                                <p className="text-[10px] text-gray-500 uppercase tracking-widest mb-1">Comissão</p>
                                <p className="text-lg font-bold text-white">{barber.commission}</p>
                            </div>
                            <div className="bg-[#0a0a0a] p-4 rounded-xl border border-[#1f1f1f] text-center">
                                <p className="text-[10px] text-gray-500 uppercase tracking-widest mb-1">Avaliação</p>
                                <p className="text-lg font-bold text-[#D4AF37]">{barber.rating} ★</p>
                            </div>
                        </div>

                        <div className="flex gap-2">
                            <Button variant="secondary" className="flex-1 text-xs uppercase font-bold tracking-widest">Editar</Button>
                            <Button variant="outline" className="px-4"><Icon name="Settings" className="w-4 h-4" /></Button>
                        </div>
                    </div>
                ))}
            </div>
        </div>
    );
}
